 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    vals = [v for row in grid for v in row if v != 2]
    bg = max(set(vals), key=vals.count)
    row_bars = [r for r in range(h) if all(v == 2 for v in grid[r])]
    col_bars = [c for c in range(w) if all(grid[r][c] == 2 for r in range(h))]
    pts = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
           if grid[r][c] not in (bg, 2)]
    if not pts:
        return [row[:] for row in grid]
    out = [[bg] * w for _ in range(h)]
    if row_bars:
        b = row_bars[0]
        if max(r for r, c, v in pts) < b:
            shift = b - 1 - max(r for r, c, v in pts)
        else:
            shift = b + 1 - min(r for r, c, v in pts)
        stripe = round(sum(r for r, c, v in pts) / len(pts))
        out[b] = [2] * w
        if 0 <= stripe < h:
            out[stripe] = [8] * w
        for r, c, v in pts:
            rr = r + shift
            if 0 <= rr < h:
                out[rr][c] = v
        return out
    if col_bars:
        b = col_bars[0]
        if max(c for r, c, v in pts) < b:
            shift = b - 1 - max(c for r, c, v in pts)
        else:
            shift = b + 1 - min(c for r, c, v in pts)
        stripe = round(sum(c for r, c, v in pts) / len(pts))
        for r in range(h):
            out[r][b] = 2
        if 0 <= stripe < w:
            for r in range(h):
                out[r][stripe] = 8
        for r, c, v in pts:
            cc = c + shift
            if 0 <= cc < w:
                out[r][cc] = v
        return out
    return [row[:] for row in grid]
